-- Migration 0025_lifecycle: generated by drizzle-kit (the tables), RLS, grants and function hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #301)
-- Data lifecycle tables (#301, part 1 of #31; docs/engineering/data-lifecycle.md):
--   * export_job: owner-requested exports built by `export.build`. Tenant table under FORCE RLS
--     (tenantPolicy()). blob_id has no FK (blob has no unique (id, workspace_id)), like
--     saas_invoice.pdf_blob_id. One queued/running export per (workspace, requester).
--     owner_definer_read lets app_export_due_jobs() list expired exports for the hourly
--     `system.export.expire` job; it returns ids only.
--   * deletion_job: workspace, account and memory deletions (#302, #303). workspace_id is null only
--     for account deletions (NULLABLE_WORKSPACE_TABLES); still FORCE RLS with ws_isolation.
--   * deletion_tombstone: global minimal record of an erased workspace (GLOBAL_TABLES); no FK so it
--     outlives the purge. Write-once: the app and clerk roles may not UPDATE, DELETE or TRUNCATE it.
-- New tables, a policy, grants and a function only: nothing existing is altered or dropped.
CREATE TABLE "deletion_job" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"workspace_id" uuid,
	"user_id" uuid,
	"kind" text NOT NULL,
	"requested_by" uuid NOT NULL,
	"status" text DEFAULT 'pending_cooloff' NOT NULL,
	"cooloff_until" timestamp with time zone,
	"erase_after" timestamp with time zone,
	"steps" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp with time zone,
	"receipt_hash" text,
	CONSTRAINT "deletion_job_kind_chk" CHECK (kind in ('workspace', 'account', 'memory')),
	CONSTRAINT "deletion_job_status_chk" CHECK (status in ('pending_cooloff', 'scheduled', 'running', 'erased', 'cancelled', 'failed')),
	CONSTRAINT "deletion_job_workspace_chk" CHECK (kind = 'account' or workspace_id is not null),
	CONSTRAINT "deletion_job_account_user_chk" CHECK (kind <> 'account' or user_id is not null)
);
--> statement-breakpoint
CREATE TABLE "deletion_tombstone" (
	"workspace_id" uuid PRIMARY KEY NOT NULL,
	"deleted_at" timestamp with time zone DEFAULT now() NOT NULL,
	"receipt_hash" text NOT NULL
);
--> statement-breakpoint
