	"expires_at" timestamp with time zone,
	"error_code" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "export_job_scope_chk" CHECK (scope in ('workspace', 'user')),
	CONSTRAINT "export_job_status_chk" CHECK (status in ('queued', 'running', 'ready', 'failed', 'expired')),
	CONSTRAINT "export_job_progress_chk" CHECK (progress between 0 and 100),
