CREATE FUNCTION app_export_due_jobs(p_now timestamptz)
  RETURNS TABLE (id uuid, workspace_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT e.id, e.workspace_id FROM export_job e
    WHERE e.status = 'ready' AND e.expires_at <= p_now
    ORDER BY e.expires_at, e.id
    LIMIT 500
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_export_due_jobs(timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_export_due_jobs(timestamptz) TO causedeck_app;--> statement-breakpoint
